package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamCultureBank1 {
  private const val T = "බෞද්ධ සංස්කෘතිය, වත්පිළිවෙත්, කලාව හා සිද්ධස්ථාන"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "බෞද්ධ සංස්කෘතිය හා වත්පිළිවෙත් අදාළ කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බෞද්ධ පූජා ක්‍රම අතරින් බුදුරදුන් ජීවමාන සමයේදී පවා අගය කළ උතුම්ම පූජාව කුමක්ද?", "ප්‍රතිපත්ති පූජාව", "ආමිස පූජාව", "මල් පහන් පූජාව", "සුවඳ දුම් පූජාව", "ප්‍රතිපත්ති පූජාව උතුම්ම පූජාව වේ."),
    q("මල්, පහන්, ගිලන්පස ආදී ද්‍රව්‍ය පූජා කිරීම බෞද්ධ සංස්කෘතියේ හැඳින්වෙන්නේ කුමන නමකින්ද?", "ආමිස පූජාව", "ප්‍රතිපත්ති පූජාව", "භාවනා පූජාව", "විදර්ශනා පූජාව", "ද්‍රව්‍යමය පූජා ආමිස පූජා වේ."),
    q("භික්ෂූන් වහන්සේලාට වස් කාලය අවසානයේදී පූජා කරනු ලබන අතිශය දුර්ලභ පුණ්‍ය කර්මය කුමක්ද?", "කඨින පින්කම", "කැලණි පෙරහැර", "අසදෘශ දානය", "පිණ්ඩපාතය", "කඨින පූජාව දුර්ලභ පින්කමකි."),
    q("වස් කාලය ආරම්භ වන්නේ බුදුදහමට අනුව කුමන පොහෝ දිනකදීද?", "ඇසළ පුන් පොහෝ දින", "වෙසක් පුන් පොහෝ දින", "නිකිණි පුන් පොහෝ දින", "බිනර පුන් පොහෝ දින", "ඇසළ පෝයෙන් පසු වස් විසීම ඇරඹේ."),
    q("දුර්භික්ෂ, රෝග හා අමනුෂ්‍ය උපද්‍රව දුරු කර ගැනීමට ශ්‍රී ලංකාවේ බෞද්ධයන් පවත්වන පුණ්‍ය කර්මය කුමක්ද?", "පිරිත් දේශනාව", "මල් පූජාව", "කඨින පින්කම", "නැකැත් කෙළිය", "පිරිත් දේශනාවෙන් සෙත් ලැබේ."),
    q("ශ්‍රී ලංකාවේ අනුරාධපුර හා පොළොන්නරු ආදී ප්‍රදේශවල පිහිටි ප්‍රධාන බෞද්ධ පූජස්ථාන අට හඳුන්වන්නේ කුමන නමකින්ද?", "අටමස්ථාන", "සොළොස්මස්ථාන", "පංච මහා විහාර", "පංචස්ථාන", "අනුරාධපුරයේ අටමස්ථාන ප්‍රසිද්ධය."),
    q("සිංහල වාස්තු විද්‍යාවේ සඳහන් 'සඳකඩපහණ' නිර්මාණය කර ඇත්තේ කුමන ස්ථානයක පිහිටුවීමටද?", "විහාරයක හෝ මාලිගාවක පියගැටපෙළ පාමුල", "ස්තූපයක මුදුනේ", "දොරටුව අසල වහලයේ", "බෝධිය වටා", "පියගැටපෙළ පාමුලඳකඩපහණ පිහිටුවයි."),
    q("සඳකඩපහණක අද්දරින්ම පෙනෙන අලංකාර රටාව කුමක්ද?", "ගිනි දැල් රටාව", "හංස පන්තිය", "අශ්ව පන්තිය", "මල් ලියවැළ", "සංසාරයේ දැවෙන ස්වභාවය ගිනි දැලින් පෙන්වයි."),
    q("විහාරයක හෝ ප්‍රාසාදයක පිවිසුම් දොරටුව දෙපස ආරක්ෂාව සඳහා නෙළන ලද රූප හඳුන්වන්නේ කුමක් ලෙසද?", "මුරගල", "කොරවක්ගල", "සඳකඩපහණ", "පියගැටපෙළ", "මුරගල දොරටුව දෙපස පිහිටා ඇත."),
    q("ප්‍රාසාදයක පියගැටපෙළ දෙපස අලංකාර ලෙස ගල්වලින් නෙළන ලද මකර රුව සහිත කොටස කුමක්ද?", "කොරවක්ගල", "මුරගල", "සඳකඩපහණ", "පිළිමගෙය", "කොරවක්ගල පියගැටපෙළ දෙපස වේ."),
    q("වෙසක් උත්සවයේදී සිහිපත් කරනු ලබන ප්‍රධාන සිදුවීම් සංඛ්‍යාව කීයද?", "තෙමඟුල (උපත්, බුද්ධත්ව, පිරිනිවන්)", "සිදුවීම් දෙකකි", "සිදුවීම් හතරකි", "සිදුවීම් පහකි", "වෙසක් පෝය තෙමඟුල සිහි කරයි."),
    q("පොසොන් පුන් පොහෝ දින ශ්‍රී ලංකාවේ ප්‍රධාන වශයෙන් සමරනු ලබන ඓතිහාසික සිදුවීම කුමක්ද?", "අනුබුදු මිහිඳු හිමියන් ලංකාවට වැඩම කර බුදුසසුන් පිහිටුවීම", "දළදා වහන්සේ වැඩමවීම", "බෝධි ශාඛාව පැමිණීම", "පළමු සංගායනාව", "පොසොන් පෝය බුදුදහම ලැබූ දිනයයි."),
    q("උඳුවප් පුන් පොහෝ දින ලංකා ඉතිහාසයේ විශේෂ වන්නේ කුමන සිදුවීම නිසාද?", "සංඝමිත්තා තෙරණිය ශ්‍රී මහා බෝධි ශාඛාව රැගෙන වැඩම කිරීම", "මිහිඳු හිමි වැඩම කිරීම", "දළදා වහන්සේ වැඩම කිරීම", "පාලි ත්‍රිපිටකය ලිවීම", "උඳුවප් පෝය බෝධි පැළය වැඩමවීමෙන් විශේෂ වේ."),
    q("නවම් පුන් පොහෝ දින බුදු සසුනේ සිදු වූ අතිශය වැදගත් ඓතිහාසික සිදුවීම කුමක්ද?", "සැරියුත් මුගලන් දෙනමට අග්‍රශ්‍රාවක තනතුරු පිරිනැමීම", "කාන්තා පැවිද්ද ලබා දීම", "පළමු සංගායනාව", "දළදා පූජාව", "නවම් පෝදා අග්‍රශ්‍රාවක තනතුරු දුන්හ."),
    q("මහනුවර ඇසළ පෙරහැරේ ප්‍රධාන අරමුණ කුමක්ද?", "ශ්‍රී දළදා වහන්සේ උදෙසා වාර්ෂික මහා පූජෝත්සවයක් පැවැත්වීම", "විනෝද වීම පමණක්", "රජුගේ බලය පෙන්වීම", "විදේශීය සංචාරකයන් ආකර්ෂණය කිරීම පමණක්", "දළදා වහන්සේ උදෙසා පෙරහැර පවත්වයි."),
    q("ශ්‍රී ලංකාවේ බෞද්ධ විහාරස්ථානයක ප්‍රධාන අංග තුන ලෙස සැලකෙන්නේ කුමක්ද?", "චෛත්‍යය, බෝධිය සහ ප්‍රතිමාගෙය", "ගොඩනැගිලි, මාලිගා, පොකුණු", "කඩමණ්ඩිය, වෙළඳසැල, පාසල", "කොඩිය, බෙරය, මල්සන", "දාගැබ, බෝධිය, විහාරය ප්‍රධාන අංග වේ."),
    q("බුදුරදුන්ගේ ධාතුන් වහන්සේ තැන්පත් කර සාදන ලද අර්ධ ගෝලාකාර ගොඩනැගිල්ල හඳුන්වන්නේ කෙසේද?", "ස්තූපය (දාගැබ / චෛත්‍යය)", "ප්‍රතිමාගෙය", "පෝයගෙය", "ධර්මශාලාව", "දාගැබ්වල ධාතු තැන්පත් කෙරේ."),
    q("බෞද්ධ සංස්කෘතියේ වැදගත් අංගයක් වන 'පිරිත් මණ්ඩපය' සකස් කරනු ලබන්නේ කෙසේද?", "මල්, පන් මඩුවලින් හා කොඩි වැල්වලින් අලංකාර ලෙස", "කළු ගලින් පමණක්", "යකඩ වලින්", "මැටිවලින් පමණක්", "පිරිත් මණ්ඩපය මල්වලින් අලංකාර කරයි."),
    q("බෞද්ධයන් විසින් බුදුරදුන්ගේ බුද්ධත්වය සිහිපත් කරමින් පවත්වන ආලෝක පූජාව කුමක්ද?", "වෙසක් පහන් කූඩු හා පහන් දැල්වීම", "ගිනි කෙළි පැවැත්වීම", "වනාන්තර පුළුස්සා දැමීම", "විදුලි බුබුළු පමණක් දැල්වීම", "පහන් දැල්වීම ආමිස පූජාවකි."),
    q("කැලණි විහාරයේ පවත්වන ප්‍රසිද්ධ සංස්කෘතික පෙරහැර කුමක්ද?", "කැලණි දුරුතු පෙරහැර", "ඇසළ පෙරහැර", "නවම් පෙරහැර", "වෙසක් පෙරහැර", "දුරුතු පෝදා කැලණි පෙරහැර පවත්වයි.")
  )
}
